void traverseAVLTree(AVLTree<int> &intTree) {
    cout << "In-order: " << endl;
    intTree.inorder();

    cout << "\nPre-order: " << endl;
    intTree.preorder();

    cout << "\nPost-order: " << endl;
    intTree.postorder();
}

